/**
 * Download a specific JSON Schema
 */
export function downloadSingleJsonSchema(schemaObj: any, filename: string) {
  const dataStr = JSON.stringify(schemaObj, null, 2);
  const blob = new Blob([dataStr], { type: 'application/json;charset=utf-8;' });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = filename;
  a.click();
  URL.revokeObjectURL(url);
}

export function downloadSongSchema() {
  downloadSingleJsonSchema(SONG_JSON_SCHEMA, `noor-song-schema-v${SONG_SCHEMA_VERSION}.json`);
}

export function downloadCoverArtSchema() {
  downloadSingleJsonSchema(COVER_ART_JSON_SCHEMA, `noor-coverart-schema-v${COVER_ART_SCHEMA_VERSION}.json`);
}

